// Captures the Champagne Silk Hero's live WebGL canvas as the production
// fallback still. Useful when the shader output differs from the
// texture-based still generated by build-silk-still.mjs.
// Prereq: dev server running on :3000 (npm run dev).
// Usage:  npm run capture:hero
import { chromium } from "playwright";
import sharp from "sharp";

const OUT = "public/images/hero/silk-still.jpg";

const browser = await chromium.launch({
  args: ["--use-gl=swiftshader", "--enable-webgl", "--ignore-gpu-blocklist"],
});
const page = await browser.newPage({
  viewport: { width: 1920, height: 1080 },
  deviceScaleFactor: 2,
});
await page.goto("http://localhost:3000/", { waitUntil: "networkidle" });
await page.addStyleTag({ content: "nextjs-portal { display: none !important; }" });
await page.waitForSelector('[data-testid="silk-hero"] canvas', { timeout: 20000 });
// Let the shader settle before freezing the frame.
await page.waitForTimeout(6000);

// Hide everything stacked above the canvas so only the background renders.
/* eslint-disable no-undef */
await page.evaluate(() => {
  const wrap = document.querySelector('[data-testid="silk-hero"]');
  const section = wrap?.parentElement;
  if (section) {
    Array.from(section.children).forEach((el) => {
      if (el !== wrap) el.style.visibility = "hidden";
    });
  }
  Array.from(document.body.children).forEach((el) => {
    if (!section || !el.contains(section)) el.style.visibility = "hidden";
  });
});
/* eslint-enable no-undef */

const png = await page.locator('[data-testid="silk-hero"]').screenshot({ type: "png" });
await browser.close();

await sharp(png).jpeg({ quality: 88, mozjpeg: true }).toFile(OUT);
const meta = await sharp(OUT).metadata();
console.log(`Wrote ${OUT} — ${meta.width}×${meta.height}`);
